/**
 * Applies every drizzle/rls/*.sql file, in lexical order, using a PRIVILEGED
 * connection (DATABASE_ADMIN_URL). RLS policies are NOT generated by
 * drizzle-kit (data-model.md) — they are hand-written and applied here, after
 * `db:migrate`. Each file is idempotent, so this is safe to re-run.
 *
 * Run via: pnpm rls:apply  (or pnpm --filter @lingua/db rls:apply)
 */
import { readFileSync, readdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { config } from "dotenv";
import { Client } from "pg";

config({ path: join(dirname(fileURLToPath(import.meta.url)), "../../../../.env") });

const adminUrl = process.env.DATABASE_ADMIN_URL ?? process.env.DATABASE_URL;
if (!adminUrl) {
  throw new Error("DATABASE_ADMIN_URL / DATABASE_URL must be set to apply RLS.");
}

const rlsDir = join(dirname(fileURLToPath(import.meta.url)), "../../drizzle/rls");

async function main(): Promise<void> {
  const files = readdirSync(rlsDir)
    .filter((f) => f.endsWith(".sql"))
    .sort();

  const client = new Client({ connectionString: adminUrl });
  await client.connect();
  try {
    for (const file of files) {
      const sqlText = readFileSync(join(rlsDir, file), "utf8");
      await client.query(sqlText);
      console.log(`  applied ${file}`);
    }
    console.log(`RLS: applied ${files.length} file(s).`);
  } finally {
    await client.end();
  }
}

main().catch((err) => {
  console.error("RLS apply failed:", err);
  process.exit(1);
});
